// Generated by scripts/assets/prep-paint-grass.mjs (the painted grasses, at the 256 px repeat) and scripts/assets/prep-photo-grass.mjs
// (the photo textures, in tile space like the asphalt mosaic). The Paint tool's grass and photo textures.
import golfFairway from '../assets/ground/paint-photo-fairway.webp';
import golfSod from '../assets/ground/paint-photo-fairway-sod.webp';
import golfRough from '../assets/ground/paint-photo-rough.webp';
import paintConcrete from '../assets/ground/paint-photo-concrete.webp';
import golfGreen from '../assets/ground/paint-grass-golf-putting-green.webp';
import lawnClover from '../assets/ground/paint-grass-backyard-clover-flowers.webp';
import lawnLush from '../assets/ground/paint-grass-backyard-lush.webp';
import lawnWorn from '../assets/ground/paint-grass-backyard-worn.webp';
import meadowFlowers from '../assets/ground/paint-grass-meadow-flowers-patches.webp';
import meadowLush from '../assets/ground/paint-grass-meadow-lush.webp';

/** a grass texture the Paint tool can lay (textures.ts stores each one; the painted ones are hex-mixed like the base grass) */
export type GrassTex = 'lawnLush' | 'lawnWorn' | 'lawnClover' | 'golfGreen' | 'golfFairway' | 'golfSod' | 'golfRough' | 'meadowLush' | 'meadowFlowers';

/** the painted grass textures in the Paint panel's order, with their painting's URL (hex-mixed, screen space) */
export const GRASS_PAINT: { tex: GrassTex; src: string }[] = [
  { tex: 'lawnLush', src: lawnLush },
  { tex: 'lawnWorn', src: lawnWorn },
  { tex: 'lawnClover', src: lawnClover },
  { tex: 'golfGreen', src: golfGreen },
  { tex: 'meadowLush', src: meadowLush },
  { tex: 'meadowFlowers', src: meadowFlowers },
];

/** the photo textures, laid in tile space like the asphalt mosaic so the mowing stripes and the paving follow the paint area's angle and scale;
 *  tex = the texture's name (a grass, or 'pad' for the Paint tool's Concrete); src is the seamless photo at its native size (1254 px grasses, 1024 px concrete);
 *  mix = the metres the photo covers when hex-mixed so it never visibly repeats (0 = a plain tile over the 12-tile period);
 *  px = the mosaic's pixels per tile when mixed (optional, default 160; 128 saves memory) */
export const PHOTO_TEX: { tex: string; src: string; mix: number; px?: number }[] = [
  { tex: 'golfFairway', src: golfFairway, mix: 0 },
  { tex: 'golfSod', src: golfSod, mix: 0 },
  { tex: 'golfRough', src: golfRough, mix: 6 },
  { tex: 'pad', src: paintConcrete, mix: 4, px: 128 },
];
/** true for a texture laid as a tile-space photo (renderer.ts drawPaints), not a screen-space painting */
export const isPhotoTex = (t: string) => PHOTO_TEX.some(p => p.tex === t);
